UPDATE ui.dashboardquery SET
vcdashboardquery =  E'{
	"Account":"select iaccountid, icustomerid, vcexternalaccountid, iaccounttypeid, vcifsc, vcaccountproviderid, vcaccountname, dtonboardingdate, dtexpirydate, imcc, bmerchant, bverified, irecordstatus, dtentrydatetime from masters.accounts where itenantid = :tenantid order by iaccountid desc limit 50000",
	"VPA": "select ivpaid, iaccountid, vcexternaladdressid, vcaddress, iproductid, vcvpaname, bverified, imcc, dtonboardingdate, dtexpirydate, bmerchant, ivpaproviderid, bprofiled, dtfirsttransaction, dtlasttransaction, irecordstatus, dtentrydatetime from masters.vpa where itenantid = :tenantid order by ivpaid desc limit 50000",
	"Customer": "SELECT icustomerid, vcexternalcustid, vccustomername, vccustomertype, vcsalutation, vcverifiedname, vcgender, dtdoidob, dtonboardingdate, vcpostalcode, vcemail, vcregisteredmobile, imcc, vcidentitytype1, vcidentitydetails1, vcidentitytype2, vcidentitydetails2, vcregisteredaddressgeolocation, iadm3, iadm2, iadm1,  vccountrycode, irecordstatus, dtentrydatetime, lastmodified, vcattribs->>''kyc'' as \\"kyc\\",vcattribs->>''risk'' as \\"risk\\",vcattribs->>''dealer_id'' as \\"dealer_id\\",vcattribs->>''gross_income'' as \\"gross_income\\",vcattribs->>''source_of_income'' as \\"source_of_income\\",vcattribs->>''termination_status'' as \\"termination_status\\",vcattribs->>''customer_onboard_type'' as \\"customer_onboard_type\\",vcattribs->>''occupation'' as \\"occupation\\",vcattribs->>''city'' as \\"city\\",vcattribs->>''state'' as \\"state\\", vcattribs->>''accountType'' as \\"accountType\\", vcattribs->>''doi_dob'' as \\"doi_dob\\", vcattribs->>''gender'' as \\"gender\\", vcattribs->>''ucic_id'' as \\"UCIC_ID\\", vcattribs->>''Mobile_no_UpdateTime'' as \\"Mobile_no_UpdateTime\\" FROM masters.customers where itenantid = :tenantid :AttribsForm order by icustomerid desc limit 50000;"
}'::text WHERE
idashboardqueryid = 48 AND itenantid = 12;

INSERT INTO ui.masterextractattribs (attribpath, level, datatype, displayname, itenantid) VALUES ('vcattribs->>''Mobile_no_UpdateTime''', 'Customer', 'String', 'Mobile_no_UpdateTime', 12);